public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {

    // Check if the genericType is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the type arguments for the genericType
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Check if the typeArguments are not empty
    if (typeArguments.length == 0) {
        return null;
    }

    // Create a list to store the resolved arguments
    List<Class<?>> resolvedArguments = new ArrayList<>();

    // Iterate over the typeArguments and resolve them
    for (Type typeArgument : typeArguments) {
        // Check if the typeArgument is a type variable
        if (typeArgument instanceof TypeVariable) {
            // Get the type variable name
            String typeVariableName = ((TypeVariable) typeArgument).getName();

            // Get the type variable from the targetType
            TypeVariable<?> typeVariable = targetType.getTypeVariable(typeVariableName);

            // Check if the typeVariable is not null
            if (typeVariable != null) {
                // Get the bounds for the typeVariable
                Type[] bounds = typeVariable.getBounds();

                // Check if the bounds are not empty
                if (bounds.length > 0) {
                    // Get the first bound
                    Type bound = bounds[0];

                    // Check if the bound is a class
                    if (bound instanceof Class) {
                        // Add the bound to the resolvedArguments list
                        resolvedArguments.add((Class<?>) bound);
                    }
                }
            }
        } else {
            // The typeArgument is not a type variable, so it must be a class
            resolvedArguments.add((Class<?>) typeArgument);
        }
    }

    // Return the resolved arguments as an array
    return resolvedArguments.toArray(new Class<?>[0]);
